steps.script:
$ErrorActionPreference='Stop'
$o=@{state='pending'}
$t=Join-Path $env:TEMP ('TTEditorialDispatch-'+[guid]::NewGuid().ToString('N')+'.ps1')
try{
 $url='https://raw.githubusercontent.com/fabricelop/europapress-rss/5cb71812c7e562ffa4ce0a52ba33a07e712104e7/windows/Reparar-TT-Editorial-20261111.ps1'
 Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $t -TimeoutSec 35
 $src=[IO.File]::ReadAllText($t,[Text.Encoding]::UTF8)
 if(-not $src.Contains('TT_EDITORIAL_SAFE_WRAPPER_V1') -or -not $src.Contains('TRANSMISSION_UNVERIFIED') -or -not $src.Contains('EnsureNotRunning')){throw 'PINNED_GUARD_MARKER_MISSING'}
 & $t *> $null
 if(-not $?){throw 'EDITORIAL_RESCUE_FAILED'}
 $o.state='dispatch_completed'
}catch{$o.state='error';$o.reason=[string]$_.Exception.Message}
finally{Remove-Item $t -Force -ErrorAction SilentlyContinue}
Write-Output ('TTRESULT:'+($o|ConvertTo-Json -Compress))
